WITH remaining_keys AS (SELECT country, customer_id FROM sessions EXCEPT DISTINCT SELECT country, customer_id FROM sessions WHERE browser = 'Safari'), reconciled AS (SELECT s.* FROM sessions s JOIN remaining_keys k ON s.country = k.country AND s.customer_id = k.customer_id) SELECT id, browser, started_at, country, CASE WHEN browser RLIKE '^(Chrome|Firefox)$' THEN 'PRIORITY' ELSE 'GROUP_B' END AS browser_zone FROM reconciled ORDER BY browser_zone DESC
